insert into public.exec_priorities (id, exec_id, version, quarter, priorities, narrative, budget_min_eur, budget_max_eur, required_compliance, dealbreakers, created_at) values ('prio_claire_v1', 'exec_claire', 1, 'Q3 2026', array['DORA register of information', 'SIEM cost reduction']::text[], 'Initial draft.', 20000, 120000, array['ISO 27001']::text[], array['blockchain']::text[], now() + interval '-8640000 seconds');
insert into public.exec_priorities (id, exec_id, version, quarter, priorities, narrative, budget_min_eur, budget_max_eur, required_compliance, dealbreakers, created_at) values ('prio_claire_v2', 'exec_claire', 2, 'Q4 2026', array['DORA compliance: automate the ICT third-party register of information and incident reporting before the January supervisory review', 'Cut SIEM and SOC tooling cost by 30% (Splunk renewal in February) without losing detection coverage', 'Roll out phishing-resistant MFA (passkeys / FIDO2) to all 2,100 staff and contractors', 'Govern employee use of generative AI: stop customer data leaking into public LLM tools', 'Prepare for TLPT (threat-led penetration testing) under DORA in H1 2027']::text[], 'We are a regulated EU payment institution (DNB/ECB supervised). Board wants measurable DORA progress by January. I prefer vendors with EU hosting and existing financial-services references. I don''t take meetings about generic ''AI-powered'' platforms, crypto, or staff augmentation.', 25000, 150000, array['ISO 27001', 'GDPR DPA']::text[], array['blockchain', 'crypto', 'staff augmentation', 'lead generation', 'offshore SOC']::text[], now() + interval '-1728000 seconds');
