insert into public.pitch_answers (one_liner, acv_band, timeline, compliance, proof_url, proof_text, pitch_id, contact_name, company_name, created_at) values ('Passkey rollout for the whole workforce in 6 weeks: device enrolment, recovery flows and Okta/Entra integration, no help-desk spike.', '25-50k', 'this_quarter', array['ISO 27001', 'SOC 2 Type II', 'GDPR DPA', 'EU data residency']::text[], 'https://keyward.io/customers', 'Rolled out FIDO2 passkeys to 4,800 staff at a Benelux bank in 7 weeks; help-desk tickets down 38% after go-live.', 'pit_keyward', 'Ana Lima', 'Keyward', now() + interval '-176400 seconds');
